import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Consider the consecutive integer set {start, start+1, ..., n}. A subset has the strong triangle property with slack [slack] if it contains three distinct elements x<y<z such that x + y > z + [slack]. Determine the largest possible n such that every [alpha]-element subset of {start, start+1, ..., n} has the strong triangle property with slack [slack].'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate parameters ensuring non-triviality and monotone recurrence.
# Constraints: alpha >= 10, start >= 5, 1 <= slack <= start-3 so s_{k+2} > s_{k+1}.
for _ in range(100):
    start = rng.randint(5, 12)
    alpha = rng.randint(10, 15)
    slack = rng.randint(1, start - 3)
    # Build the minimal forbidden-sequence via s_{k+2} = s_{k+1} + s_k - slack
    s = [None]*(alpha)
    s[0] = start
    s[1] = start + 1
    ok = True
    for k in range(2, alpha):
        s[k] = s[k-1] + s[k-2] - slack
        if s[k] <= s[k-1]:
            ok = False
            break
    if not ok:
        continue
    # Ensure the instance is sizeable (to avoid trivial tiny answers)
    if s[-1] - 1 - start < 30:
        continue
    return {'alpha': alpha, 'start': start, 'slack': slack}
# Fallback deterministic safe instance
start = 7
alpha = 12
slack = 3
return {'alpha': alpha, 'start': start, 'slack': slack}

    def verifier(assign):
# Validate presence and types
if not all(k in assign for k in ('alpha','start','slack')):
    # Missing keys
    return (False, None)
alpha = assign['alpha']
start = assign['start']
slack = assign['slack']
# Type checks
if not (isinstance(alpha, int) and isinstance(start, int) and isinstance(slack, int)):
    # Non-integer inputs
    return (False, None)
# Domain constraints to enforce difficulty and monotonicity
if alpha < 10:
    # Too easy; require larger subsets for difficulty
    return (False, None)
if start < 5:
    # Start too small may cause edge cases; we require start>=5
    return (False, None)
if slack < 1 or slack > start - 3:
    # Slack must be positive and small enough to keep sequence strictly increasing
    return (False, None)
# Build the minimal 'strong-triangle-free' sequence with recurrence:
# s1 = start, s2 = start+1, and for k>=3, s_k = s_{k-1} + s_{k-2} - slack.
s = [None]*alpha
s[0] = start
s[1] = start + 1
for k in range(2, alpha):
    s[k] = s[k-1] + s[k-2] - slack
    # Ensure strict increase to model distinct elements in an increasing subset
    if s[k] <= s[k-1]:
        # Violates monotonicity; invalid instance
        return (False, None)
# The threshold logic (theoretical justification):
# If n >= s_alpha, the subset {s_1, ..., s_alpha} lies in {start, ..., n} and satisfies
# x+y <= z+slack for all triples, hence it lacks the strong triangle property.
# Conversely, if n <= s_alpha - 1, no alpha-element subset can avoid the property,
# because any alpha-element increasing sequence must have max >= s_alpha to be strong-triangle-free.
answer = s[-1] - 1
# Additional difficulty check: ensure the interval size is reasonably large.
if answer - start + 1 < alpha + 15:
    # If the interval is too small beyond the subset size, the instance may be trivial.
    return (False, None)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

